test("exactly 30 calendar days is accepted", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-01" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});

test("29 calendar days is rejected", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-06-30" }),
    { accepted: false, daysUntilExpiry: 29 }
  );
});

test("one day above the threshold is accepted", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-02" }),
    { accepted: true, daysUntilExpiry: 31 }
  );
});

test("first day of a month exactly 30 returns both fields", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-03-01", expiryDate: "2026-03-31" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});

test("last day of a 31-day month exactly 30 is accepted", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-05-31", expiryDate: "2026-06-30" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});

test("last day of a 30-day month one below the threshold is rejected", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-04-30", expiryDate: "2026-05-29" }),
    { accepted: false, daysUntilExpiry: 29 }
  );
});

test("first of a month across a year boundary one above the threshold is accepted", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-01-01", expiryDate: "2026-02-01" }),
    { accepted: true, daysUntilExpiry: 31 }
  );
});

test("last day of December into January exactly 30 is accepted", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2025-12-31", expiryDate: "2026-01-30" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});

test("check on a leap day exactly 30 is accepted", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2024-02-29", expiryDate: "2024-03-30" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});

test("expiry on a leap day one below the threshold is rejected", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2024-01-31", expiryDate: "2024-02-29" }),
    { accepted: false, daysUntilExpiry: 29 }
  );
});

test("last day of non-leap February exactly 30 is accepted", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-02-28", expiryDate: "2026-03-30" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});

test("span of unequal month lengths counts 61 calendar days and is accepted", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-01-15", expiryDate: "2026-03-17" }),
    { accepted: true, daysUntilExpiry: 61 }
  );
});

test("fewer than 30 but still after the check date is rejected", function () {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-08-10", expiryDate: "2026-08-20" }),
    { accepted: false, daysUntilExpiry: 10 }
  );
});
